    private static AreaLevel Parse(int index, string name, string description, string[] rows)
    {
        var grid = new CellKind[20, 20];
        var pois = new List<AreaPoi>();
        if (rows.Length != 20 || rows.Any(row => row.Length != 20))
            throw new ArgumentException("Area maps must contain exactly twenty 20-character rows.", nameof(rows));
        for (int y = 0; y < 20; y++)
            for (int x = 0; x < 20; x++)
            {
                char marker = rows[y][x];
                grid[x, y] = marker == '#' ? CellKind.Wall : CellKind.Floor;
                var poi = Poi(marker, x, y);
                if (poi != null) pois.Add(poi);
            }
        return new AreaLevel(index, name, description, grid, pois);
    }

    private static AreaPoi? Poi(char marker, int x, int y) => marker switch
    {
        'T' => new AreaPoi(x, y, "Town", "A settlement where the party can prepare for the road ahead."),
        'D' => new AreaPoi(x, y, "Door", "A marked door or gateway into the next section."),
        'I' => new AreaPoi(x, y, "Item", "A notable item or treasure location."),
        'N' => new AreaPoi(x, y, "Non-player character", "A possible encounter with a resident, guide, or guardian."),
        'E' => new AreaPoi(x, y, "Exit", "A route out of the current area."),
        'S' => new AreaPoi(x, y, "Stairs", "A stairway or change in elevation."),
        'B' => new AreaPoi(x, y, "Boss", "A dangerous guardian or major encounter."),
        _ => null
    };
}
